CREATE OR REPLACE FUNCTION public.tenant_iam_admin_users_sod_baseline_v1(p_actor_email text, p_actor_session_id uuid, p_actor_session_version integer, p_release_sha text, p_tenant_id uuid, p_limit integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE result_value jsonb; enriched jsonb:='[]'; item jsonb; proof jsonb;
BEGIN
 -- Nothing beyond the identity- and release-checked directory the caller can already see.
 result_value:=public.tenant_iam_admin_view_v4(p_actor_email,p_actor_session_id,p_actor_session_version,p_release_sha,'users',p_tenant_id,p_limit);
 IF p_tenant_id IS NULL OR jsonb_typeof(result_value->'users') IS DISTINCT FROM 'array'
   OR result_value->'users' IS DISTINCT FROM result_value->'items' THEN RETURN result_value; END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(result_value->'users') LOOP
   item:=item-'sodEditBaseline';
   proof:=public.tenant_iam_current_pair_evidence_v1(p_tenant_id,item);
   IF proof IS NOT NULL THEN item:=item||jsonb_build_object('sodEditBaseline',proof); END IF;
   enriched:=enriched||jsonb_build_array(item);
 END LOOP;
 RETURN result_value||jsonb_build_object('users',enriched,'items',enriched);
END $function$

CREATE OR REPLACE FUNCTION public.tenant_iam_admin_view_v4(p_actor_email text, p_actor_session_id uuid, p_actor_session_version integer, p_release_sha text, p_resource text, p_tenant_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  result_value jsonb;
  users_value jsonb := '[]'::jsonb;
  tenant_ready boolean := false;
BEGIN
  result_value := tenant_iam_admin_view_v3(
    p_actor_email, p_actor_session_id, p_actor_session_version,
    p_release_sha, p_resource, p_tenant_id, p_limit
  );

  IF p_tenant_id IS NULL OR p_resource NOT IN ('bootstrap', 'users') THEN
    RETURN result_value;
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM platform_tenant tenant
    JOIN tenant_identity_policy policy
      ON policy.tenant_id = tenant.id
     AND policy.tenant_data_plane_ready IS TRUE
     AND policy.certified_release_sha = p_release_sha
    JOIN platform_tenant_source_binding binding
      ON binding.id = policy.certified_source_binding_id
     AND binding.tenant_id = tenant.id
     AND binding.source_system = 'GRH'
     AND binding.verified IS TRUE
    WHERE tenant.id = p_tenant_id AND tenant.status = 'active'
  ) INTO tenant_ready;

  IF p_resource = 'users' THEN
    SELECT COALESCE(jsonb_agg(
      CASE WHEN account.identity_version IS NULL THEN item.value
        ELSE item.value || jsonb_build_object('identityVersion', account.identity_version)
      END ORDER BY item.ordinality
    ), '[]'::jsonb)
      INTO users_value
    FROM jsonb_array_elements(COALESCE(result_value->'users', '[]'::jsonb))
      WITH ORDINALITY AS item(value, ordinality)
    LEFT JOIN internal_users account
      ON lower(account.email) = lower(item.value->>'email');

    result_value := jsonb_set(result_value, '{users}', users_value, true);
    result_value := jsonb_set(result_value, '{items}', users_value, true);
  END IF;

  IF tenant_ready AND NOT EXISTS (
    SELECT 1
    FROM jsonb_array_elements_text(
      COALESCE(result_value->'allowedCommands', '[]'::jsonb)
    ) command(value)
    WHERE command.value = 'update_account_profile'
  ) THEN
    result_value := jsonb_set(
      result_value,
      '{allowedCommands}',
      COALESCE(result_value->'allowedCommands', '[]'::jsonb)
        || jsonb_build_array('update_account_profile'),
      true
    );
  END IF;

  RETURN result_value;
END
$function$

CREATE OR REPLACE FUNCTION public.tenant_iam_admin_view(p_actor_email text, p_resource text, p_limit integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  actor internal_users%ROWTYPE;
  safe_limit integer := LEAST(GREATEST(COALESCE(p_limit, 100), 1), 200);
  tenants jsonb;
  roles jsonb;
  users_payload jsonb;
  events_payload jsonb;
  exclusive_payload jsonb;
BEGIN
  IF NOT tenant_iam_is_platform_owner(p_actor_email) THEN
    RAISE EXCEPTION 'TENANT_IAM_NOT_AUTHORIZED' USING ERRCODE = 'P0001';
  END IF;
  SELECT * INTO STRICT actor FROM internal_users
    WHERE lower(email) = lower(btrim(p_actor_email)) AND active IS TRUE LIMIT 1;

  SELECT COALESCE(jsonb_agg(to_jsonb(item) ORDER BY item."legalName"), '[]'::jsonb) INTO tenants
  FROM (
    SELECT tenant.id, tenant.slug, tenant.legal_name AS "legalName",
           tenant.short_name AS "shortName", tenant.tenant_kind AS kind,
           tenant.jurisdiction, tenant.status, tenant.version,
           crm.implementation_stage AS "implementationStage",
           crm.next_action AS "nextAction", crm.next_action_at AS "nextActionAt"
    FROM platform_tenant tenant
    LEFT JOIN platform_crm_account crm ON crm.tenant_id = tenant.id
  ) item;

  SELECT COALESCE(jsonb_agg(to_jsonb(role_item) ORDER BY role_item.label), '[]'::jsonb) INTO roles
  FROM (
    SELECT role.role_key AS key, role.label, role.description, role.scope_kind AS "scopeKind",
      COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
          'key', capability.capability_key,
          'label', capability.label,
          'description', capability.description,
          'conflictsWith', COALESCE((
            SELECT jsonb_agg(other_key ORDER BY other_key)
            FROM (
              SELECT conflict.conflicts_with_key AS other_key
              FROM iam_capability_conflict conflict
              WHERE conflict.capability_key = capability.capability_key
              UNION
              SELECT conflict.capability_key AS other_key
              FROM iam_capability_conflict conflict
              WHERE conflict.conflicts_with_key = capability.capability_key
            ) conflicts
          ), '[]'::jsonb)
        ) ORDER BY capability.capability_key)
        FROM iam_role_capability role_capability
        JOIN iam_capability capability ON capability.capability_key = role_capability.capability_key
        WHERE role_capability.role_key = role.role_key
      ), '[]'::jsonb) AS capabilities
    FROM iam_role role
  ) role_item;

  SELECT COALESCE(jsonb_agg(to_jsonb(item) ORDER BY item."displayName"), '[]'::jsonb) INTO users_payload
  FROM (
    SELECT membership.id, membership.tenant_id AS "tenantId", membership.user_email AS email,
           users.display_name AS "displayName", membership.role_key AS "roleKey",
           membership.status, membership.version,
           COALESCE((SELECT jsonb_agg(effective.capability_key ORDER BY effective.capability_key)
             FROM tenant_iam_effective_capabilities(membership.id) effective), '[]'::jsonb) AS capabilities
    FROM tenant_membership membership
    JOIN internal_users users ON lower(users.email) = lower(membership.user_email)
    LIMIT safe_limit
  ) item;

  SELECT COALESCE(jsonb_agg(to_jsonb(item) ORDER BY item."occurredAt" DESC), '[]'::jsonb) INTO events_payload
  FROM (
    SELECT event.id, event.actor_user_email AS "actorEmail",
           event.tenant_id AS "tenantId", event.membership_id AS "membershipId",
           event.command, event.target_type AS "targetType", event.target_id AS "targetId",
           event.outcome, event.occurred_at AS "occurredAt"
    FROM tenant_iam_event event ORDER BY event.occurred_at DESC LIMIT safe_limit
  ) item;

  SELECT COALESCE(jsonb_agg(to_jsonb(item) ORDER BY item."assignedAt" DESC), '[]'::jsonb) INTO exclusive_payload
  FROM (
    SELECT assignment.id, assignment.tenant_id AS "tenantId",
           assignment.capability_key AS "capabilityKey", assignment.membership_id AS "membershipId",
           assignment.assigned_at AS "assignedAt"
    FROM tenant_exclusive_capability assignment WHERE assignment.active IS TRUE
  ) item;

  IF p_resource = 'bootstrap' THEN
    RETURN jsonb_build_object(
      'user', jsonb_build_object(
        'email', lower(actor.email), 'displayName', actor.display_name, 'platformRole', 'PLATFORM_OWNER'
      ),
      'context', jsonb_build_object(
        'mode', 'platform', 'tenantAwareGateway', false,
        'message', 'Las invitaciones quedan preparadas e inactivas hasta certificar el gateway tenant-aware.'
      ),
      'tenants', tenants, 'roles', roles,
      'allowedCommands', jsonb_build_array(
        'create_tenant', 'invite_user', 'update_access',
        'suspend_membership', 'assign_exclusive_capability'
      ),
      'controls', jsonb_build_object(
        'sodReady', true, 'auditReady', true,
        'invitationGatewayReady', false, 'tenantDataPlaneReady', false
      ),
      'exclusiveAssignments', exclusive_payload
    );
  ELSIF p_resource = 'tenants' THEN
    RETURN jsonb_build_object('items', tenants, 'tenants', tenants);
  ELSIF p_resource = 'users' THEN
    RETURN jsonb_build_object('items', users_payload, 'users', users_payload);
  ELSIF p_resource = 'roles' THEN
    RETURN jsonb_build_object('items', roles, 'roles', roles);
  ELSIF p_resource = 'audit' THEN
    RETURN jsonb_build_object('items', events_payload, 'events', events_payload);
  END IF;
  RAISE EXCEPTION 'TENANT_IAM_RESOURCE_INVALID' USING ERRCODE = 'P0001';
END
$function$

CREATE OR REPLACE FUNCTION public.tenant_iam_current_pair_evidence_v1(p_tenant_id uuid, p_item jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE membership_row public.tenant_membership%ROWTYPE; pairs jsonb; effective text[];
BEGIN
   SELECT * INTO membership_row FROM public.tenant_membership m WHERE m.tenant_id=p_tenant_id
     AND m.id::text=p_item->>'id' AND m.tenant_id::text=p_item->>'tenantId'
     AND m.status='active' AND m.role_key=p_item->>'roleKey' AND m.version::text=p_item->>'version';
   IF FOUND THEN
     -- Existing pairs may be described only when the same actual guard used by update_access
     -- accepts the whole CURRENT membership. Nothing here validates or authorizes a new pair.
     BEGIN
       PERFORM public.tenant_iam_assert_no_sod_conflict(membership_row.id);
       SELECT coalesce(array_agg(e.capability_key::text),ARRAY[]::text[]) INTO effective
         FROM public.tenant_iam_effective_capabilities(membership_row.id) e;
       -- Only attest capabilities already present in the projection v4 authorized
       -- for this row. A concurrent change, future redaction, or malformed row
       -- must not disclose a previously hidden pair through this supplement.
       IF jsonb_typeof(p_item->'capabilities') IS DISTINCT FROM 'array' THEN RETURN NULL; END IF;
       IF EXISTS (SELECT 1 FROM jsonb_array_elements(p_item->'capabilities') c WHERE jsonb_typeof(c)<>'string')
          OR NOT (to_jsonb(effective) @> (p_item->'capabilities') AND (p_item->'capabilities') @> to_jsonb(effective))
         THEN RETURN NULL; END IF;
       SELECT coalesce(jsonb_agg(jsonb_build_array(f.capability_key,f.conflicts_with_key)
                  ORDER BY f.capability_key,f.conflicts_with_key),'[]'::jsonb) INTO pairs
         FROM public.iam_capability_conflict f WHERE f.capability_key=ANY(effective) AND f.conflicts_with_key=ANY(effective);
       RETURN jsonb_build_object(
         'schema','iam.current-pairs.v1','tenantId',membership_row.tenant_id,'membershipId',membership_row.id,
         'membershipVersion',membership_row.version,'roleKey',membership_row.role_key,'pairs',pairs);
     EXCEPTION WHEN raise_exception THEN
       IF SQLERRM<>'TENANT_IAM_SOD_CONFLICT' THEN RAISE; END IF;
       -- Keep this row visible for inspection but grant no client-side baseline.
     END;
   END IF;
   RETURN NULL;
END $function$
